// spec: Реклама — где показывается и где нет
// seed: tests/seed.user.spec.ts
import { test, expect } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

test.describe('Реклама — где показывается и где нет', () => {
  test('Нет рекламы на /emergency и в 5 темах первой помощи #840d8543 #a5b844f5 @iphone @prod-safe', async ({ page }) => {
    // Open /emergency ("עזרה דחופה") and assert no ad label
    await page.goto('/emergency');
    await expect(page.getByRole('heading', { name: 'עזרה דחופה' }).first()).toBeVisible();
    await expect(page.getByText('פרסומת').locator('visible=true')).toHaveCount(0);

    const topics = [
      { name: 'החייאה', url: /\/emergency\/cpr/ },
      { name: 'טביעה', url: /\/emergency\/drowning/ },
      { name: 'דימום', url: /\/emergency\/bleeding/ },
      { name: 'שברים', url: /\/emergency\/fractures/ },
      { name: 'איבוד הכרה', url: /\/emergency\/unconscious/ },
    ];

    for (const topic of topics) {
      // Open topic, assert no ad label, go back
      await page.getByRole('button', { name: topic.name }).locator('visible=true').first().click();
      await expect(page).toHaveURL(topic.url);
      await expect(page.getByText('פרסומת').locator('visible=true')).toHaveCount(0);
      await page.getByRole('button', { name: 'חזרה' }).locator('visible=true').first().click();
      await expect(page).toHaveURL(/\/emergency$/);
      await expect(page.getByRole('heading', { name: 'הוראות עזרה ראשונה' }).locator('visible=true')).toBeVisible();
    }
  });
});
